Object.assign(ID_ACTIONS,{
 pfIdentityEmail:()=>{openDlg(`${dlgHead('Alterar e-mail','Confirme a senha atual e informe o novo endereço.')}<form id="pfEmailF" class="fgrid one"><label class="fld"><span class="fl">Senha atual</span><input name="password" type="password" required autocomplete="current-password"></label><label class="fld"><span class="fl">Novo e-mail</span><input name="email" type="email" required></label><div class="dfoot"><button class="btn sec" type="button" data-a="closeDlg">Cancelar</button><button class="btn pri" type="submit">Enviar código</button></div></form>`,'sm');$('#pfEmailF').onsubmit=e=>{e.preventDefault();const email=e.target.elements.email.value;idWebCode('Confirmar novo e-mail','Código enviado para '+email,()=>{ME.email=email;admRe();toast('E-mail atualizado · demonstração');});};},
 pfIdentityDownload:()=>{openDlg(`${dlgHead('Pedir meus dados','Demonstração, sem dados reais.')}<p class="who">Preparamos um arquivo com os seus dados e enviamos o link para o seu e-mail quando estiver pronto.</p><div class="dfoot"><button class="btn sec" data-a="closeDlg">Agora não</button><button class="btn pri" data-a="pfIdentityAsk">Pedir arquivo</button></div>`,'sm');},
 pfIdentityAsk:()=>{closeDlg();toast('Pedido registrado · o link chega por e-mail quando o arquivo estiver pronto');},
 pfIdentityFile:()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({demonstracao:true,nome:ME.n,email:ME.email},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='alva-dados-demonstracao.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Arquivo demonstrativo baixado');},
 pfIdentityDelete:()=>openDlg(`${dlgHead('Excluir minha conta','Sua conta será bloqueada e você sairá da igreja. Não há como voltar atrás nem reativar.')}<p class="who">Os dados são apagados quando o arquivo com eles estiver pronto. O link do arquivo chega por e-mail e vale 90 dias. Permanecem o nome, os registros de retenção obrigatória e a auditoria. Quem voltar precisa criar uma conta nova, sem o histórico.</p><div class="dfoot"><button class="btn sec" data-a="closeDlg">Manter conta</button><button class="btn dang" data-a="pfIdentityDeleteCode">Enviar código</button></div>`,'sm'),
 pfIdentityDeleteCode:()=>idWebCode('Confirmar exclusão','Código enviado para '+ME.email,()=>openDlg(`${dlgHead('Exclusão solicitada','Fim da demonstração. Nenhuma conta real foi excluída. O link dos seus dados será enviado por e-mail.')}<button class="btn pri" data-a="closeDlg">Fechar</button>`,'sm'))
});
document.addEventListener('submit',e=>{if(e.target.id!=='pfIdentityF')return;e.preventDefault();const f=e.target.elements;ME.first=f.first.value.trim();ME.n=ME.first+' '+f.surname.value.trim();ME.tel=f.tel.value;ME.nasc=f.nasc.value;admRe();toast('Dados salvos');});

