function nxDecorateContent(){
 if(!['pregacoes','musicas','material','jornadas','cursos','videos','series'].includes(S.active))return;
 const id=S.active==='pregacoes'?S.preg:S.active==='material'?S.mat:S.active==='jornadas'||S.active==='cursos'?S.cur||S.jor:S.active==='videos'?S.nxVideo:S.active==='series'?S.nxSeries:S.active==='musicas'?S.song:null;
 if(!id||$('#nxPublicationF'))return;
 if(['pregacoes','musicas','material','videos'].includes(S.active)&&ctTab(id)!=='det')return;
 if(S.aula&&(S.active==='cursos'||S.active==='jornadas'))return;
 if(S.active==='series'&&S.nxSeriesTab&&S.nxSeriesTab!=='items')return;
 if(S.active==='cursos'||S.active==='jornadas'){if(S.cur?S.ctab!=='det':S.jtab!=='trilha')return;}
 const o=[...nxAllContent(),...NX_VIDEOS,...NX_SERIES].find(x=>x.id===id),wrap=$('#main .wrap');if(!o||!wrap)return;
 wrap.insertAdjacentHTML('beforeend',`<section class="card pc nx-publication-card"><form id="nxPublicationF" class="fgrid nx-content-form">${nxFields(o)}<div class="dfoot"><button type="submit" class="btn pri">Salvar publicação</button></div></form></section>`);
 const f=$('#nxPublicationF');nxBindVis(f,o);f.onsubmit=e=>{e.preventDefault();nxSaveVisibility(o,f);toast('Publicação atualizada');};
 // The unified publication section replaces the old standalone ministry control.
 if(S.active==='pregacoes')$$('#pgF .ct-vin').forEach(el=>el.closest('.fld').hidden=true);
 if(S.active==='cursos'&&CSOLO.some(j=>j.courses.includes(o))){const box=$('#main .ct-cpos');if(box){box.querySelector('.ct-vin')?.setAttribute('hidden','');box.querySelector('#cuMinW')?.setAttribute('hidden','');const title=box.querySelector('.fl');if(title?.textContent==='Vínculo')title.hidden=true;}}
}
let nxDecQueued=false;new MutationObserver(()=>{if(nxDecQueued)return;nxDecQueued=true;queueMicrotask(()=>{nxDecQueued=false;nxDecorateContent();});}).observe(document.getElementById('main'),{childList:true,subtree:true});
