const nxFormTypes={pgNF:()=>PREGS,sgF:()=>SONGS,mtF:()=>MATS,csF:()=>[...JORNS,...CSOLO].flatMap(j=>j.courses),smF:()=>S.active==='jornadas'?(S.jor?JORNS.flatMap(j=>j.courses):JORNS):[]};
new MutationObserver(()=>{Object.entries(nxFormTypes).forEach(([id,get])=>{const f=$('#'+id);if(!f||f.dataset.nxReady)return;if(id==='smF'&&!/^(Nova jornada|Novo curso)$/.test(f.parentElement.querySelector('h2,h3')?.textContent||''))return;f.dataset.nxReady='1';const old=get().slice(),name=f.elements.n?.value||f.elements.t?.value,existing=old.find(o=>(o.n||o.t)===name),obj=existing||{};const footer=f.querySelector('.dfoot');if(!footer)return;footer.insertAdjacentHTML('beforebegin',nxFields(obj));f.querySelectorAll('.ct-vin').forEach(el=>el.closest('.fld').hidden=true);nxBindVis(f,obj);f.addEventListener('submit',()=>{const settings={min:f.elements.nxMin.value,visibility:f.elements.nxVisibility.value};setTimeout(()=>{const added=get().find(o=>!old.includes(o))||existing;if(added){if(!nxParentVis(added))Object.assign(added,settings);if(document.getElementById('main'))render();}},1100);});});}).observe(document.body,{childList:true,subtree:true});

